def obtener_ruta_cookies() -> Optional[str]:
    """
    Retorna la ruta absoluta hacia un archivo de cookies funcional.
    1. Revisa si existe la variable de entorno YOUTUBE_COOKIES.
    2. Revisa si existe el archivo local api/cookies.txt.
    3. Si no, escribe las cookies sanitizadas en /tmp (compatible con Vercel/AWS Lambda).
    """
    # 1. Variable de entorno personalizada
    env_content = os.environ.get("YOUTUBE_COOKIES")
    if env_content and env_content.strip():
        tmp_env = os.path.join(tempfile.gettempdir(), "yt_cookies_env.txt")
        try:
            with open(tmp_env, "w", encoding="utf-8") as f:
                f.write(env_content.strip() + "\n")
            return tmp_env
        except Exception as e:
            logger.warning("Error al escribir cookies desde variable de entorno: %s", e)

    # 2. Archivo físico local en api/cookies.txt
    directorio_actual = os.path.dirname(__file__)
    ruta_local = os.path.join(directorio_actual, "cookies.txt")
    if os.path.exists(ruta_local) and os.path.getsize(ruta_local) > 20:
        return ruta_local

    # 3. Fallback embebido persistido en /tmp
    tmp_fallback = os.path.join(tempfile.gettempdir(), "yt_cookies_fallback.txt")
    try:
        with open(tmp_fallback, "w", encoding="utf-8") as f:
            f.write(SANITIZED_COOKIES.strip() + "\n")
        return tmp_fallback
    except Exception as e:
        logger.error("Error al generar archivo temporal de cookies en /tmp: %s", e)
        return None
